/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { BindingEnergyScreen } from "../../src/binding-energy/BindingEnergyScreen.js";
import { ChartScreen } from "../../src/chart/ChartScreen.js";
import { SharedModel } from "../../src/common/model/SharedModel.js";
import { DecayChainsScreen } from "../../src/decay-chains/DecayChainsScreen.js";
import { HalfLivesScreen } from "../../src/half-lives/HalfLivesScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IsobarsScreen } from "../../src/isobars/IsobarsScreen.js";
import NuclideChartColors from "../../src/NuclideChartColors.js";
import { NuclideChartPreferencesModel } from "../../src/preferences/NuclideChartPreferencesModel.js";
import { ShellsScreen } from "../../src/shells/ShellsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from nuclideChartQueryParameters.
  const simPreferences = new NuclideChartPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // State every screen shares: the selected nuclide, the magic-number guides, the definition of stable.
  const shared = new SharedModel();

  const screens = [
    new ChartScreen(shared, {
      name: stringManager.getScreenNames().chartStringProperty,
      tandem: Tandem.ROOT.createTandem("chartScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
    new BindingEnergyScreen(shared, simPreferences, {
      name: stringManager.getScreenNames().bindingEnergyStringProperty,
      tandem: Tandem.ROOT.createTandem("bindingEnergyScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
    new ShellsScreen(shared, {
      name: stringManager.getScreenNames().shellsStringProperty,
      tandem: Tandem.ROOT.createTandem("shellsScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
    new IsobarsScreen(shared, {
      name: stringManager.getScreenNames().isobarsStringProperty,
      tandem: Tandem.ROOT.createTandem("isobarsScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
    new HalfLivesScreen(shared, {
      name: stringManager.getScreenNames().halfLivesStringProperty,
      tandem: Tandem.ROOT.createTandem("halfLivesScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
    new DecayChainsScreen(shared, {
      name: stringManager.getScreenNames().decayChainsStringProperty,
      tandem: Tandem.ROOT.createTandem("decayChainsScreen"),
      backgroundColorProperty: NuclideChartColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { NuclideChartColors, stringManager, simPreferences, shared } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
